def solve():
    H, W = map(int, input().split())
    grid = [input() for _ in range(H)]

    def is_safe(r, c):
        if grid[r][c] == '#':
            return False

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == '#':
                return False
        return True

    def bfs(start_r, start_c):
        if not is_safe(start_r, start_c):
            return 0

        visited = [[False] * W for _ in range(H)]
        q = [(start_r, start_c)]
        visited[start_r][start_c] = True
        count = 0

        while q:
            r, c = q.pop(0)
            count += 1

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and not visited[nr][nc] and is_safe(nr, nc):
                    q.append((nr, nc))
                    visited[nr][nc] = True
        return count

    max_freedom = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                max_freedom = max(max_freedom, bfs(r, c))

    print(max_freedom)

