def longestSpecialSubstring(s):
    def get_all_substrings(s):
        substrings = []
        n = len(s)
        for i in range(n):
            for j in range(i + 1, n + 1):
                substrings.append(s[i:j])
        return substrings

    # Get all substrings
    all_substrings = get_all_substrings(s)

    # Filter special substrings (made up of only a single character)
    special_substrings = []
    for substring in all_substrings:
        if len(set(substring)) == 1:  # All characters are the same
            special_substrings.append(substring)

    # Count frequency of each special substring
    substring_count = {}
    for substring in special_substrings:
        substring_count[substring] = substring_count.get(substring, 0) + 1

    # Find the longest special substring that occurs at least thrice
    max_length = -1
    for substring, count in substring_count.items():
        if count >= 3:
            max_length = max(max_length, len(substring))

    return max_length
