                return 1  # Takahashi wins
            elif line == [-1, -1, -1]:
                return -1  # Aoki wins
        return 0  # No winner yet

    # Check if board is full
    def is_full(board):
        for i in range(3):
            for j in range(3):
                if board[i][j] == 0:
                    return False
        return True

    # Get available moves
    def get_moves(board):
        moves = []
        for i in range(3):
            for j in range(3):
                if board[i][j] == 0:
                    moves.append((i, j))
        return moves

    # Minimax with alpha-beta pruning
    # Returns (score_diff, winner) where score_diff is from current player's perspective
    def minimax(board, scores, player, alpha, beta):
        winner_check = check_winner(board)
        if winner_check == 1:
            return (float('inf'), 1)  # Takahashi wins
        elif winner_check == -1:
            return (float('-inf'), -1)  # Aoki wins
        elif is_full(board):
            # Game ends by score
            score_diff = scores[0] - scores[1]  # Takahashi - Aoki
            if score_diff > 0:
                return (float('inf'), 1)
            elif score_diff < 0:
                return (float('-inf'), -1)
            else:
                # According to constraints, total sum is odd, so tie by score is impossible
                return (0, 0)

        moves = get_moves(board)
        current_player = player  # 1 for Takahashi, -1 for Aoki

        if current_player == 1:  # Maximizing player (Takahashi)
            max_eval = float('-inf')
            best_winner = 0
            for i, j in moves:
                new_board = deepcopy(board)
                new_scores = scores[:]
                new_board[i][j] = 1
                new_scores[0] += grid[i][j]

                eval_score, winner = minimax(new_board, new_scores, -1, alpha, beta)
                if eval_score > max_eval:
                    max_eval = eval_score
                    best_winner = winner

                alpha = max(alpha, eval_score)
                if beta <= alpha:
                    break
            return (max_eval, best_winner)
        else:  # Minimizing player (Aoki)
            min_eval = float('inf')
            best_winner = 0
            for i, j in moves:
                new_board = deepcopy(board)
                new_scores = scores[:]
                new_board[i][j] = -1
                new_scores[1] += grid[i][j]

                eval_score, winner = minimax(new_board, new_scores, 1, alpha, beta)
                if eval_score < min_eval:
                    min_eval = eval_score
                    best_winner = winner

                beta = min(beta, eval_score)
                if beta <= alpha:
                    break
            return (min_eval, best_winner)

    # Initial scores: [Takahashi, Aoki]
    initial_scores = [0, 0]

    # Start with Takahashi (player 1)
    _, winner = minimax(board, initial_scores, 1, float('-inf'), float('inf'))

    if winner == 1:
        print("Takahashi")
    else:
        print("Aoki")

