def minimizeStringValue(s):
    # Count the fixed characters and number of question marks
    fixed_count = {}
    q_indices = []

    for i, char in enumerate(s):
        if char == '?':
            q_indices.append(i)
        else:
            fixed_count[char] = fixed_count.get(char, 0) + 1

    num_q = len(q_indices)
    if num_q == 0:
        return s

    # Determine the optimal letters to use for replacements
    # We want to minimize the cost, so we should distribute letters as evenly as possible
    # Use a greedy approach: at each step, choose the letter that would add minimal additional cost

    # Start with 0 counts for all letters
    total_count = {chr(ord('a') + i): 0 for i in range(26)}

    # Add the fixed counts
    for char, count in fixed_count.items():
        total_count[char] += count

    # For the question marks, we need to decide which letters to use
    # The cost added by placing a letter c at any position is equal to its current count
    # So we should always pick the letter with minimum current count
    # In case of ties, pick the lexicographically smallest

    q_replacements = []

    for _ in range(num_q):
        # Find letter with minimum count (lexicographically smallest in case of ties)
        min_count = min(total_count.values())
        for c in sorted(total_count.keys()):  # This ensures lexicographical ordering
            if total_count[c] == min_count:
                q_replacements.append(c)
                total_count[c] += 1
                break

    # Now construct the result string
    result = list(s)
    q_replacement_iter = iter(q_replacements)

    for i in range(len(result)):
        if result[i] == '?':
            result[i] = next(q_replacement_iter)

    return ''.join(result)
