def waysToReachStair(k):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(stair, jump, last_down):
        # Base cases
        if stair == k:
            return 1

        # If we've gone too far and can't come back
        if stair > k + 1:
            return 0

        total = 0

        # Operation 1: Go down to stair - 1 (if possible)
        if stair > 0 and not last_down:
            total += dp(stair - 1, jump, True)

        # Operation 2: Go up to stair + 2^jump
        if jump < 60:  # Prevent overflow, 2^60 is way beyond constraint
            total += dp(stair + (1 << jump), jump + 1, False)

        return total

    # Start from stair 1 with jump=0, last_down=False
    return dp(1, 0, False)
