def minOperations(nums, k):
    nums.sort()
    n = len(nums)
    median_idx = (n - 1) // 2  # For 0-indexed array, this gives the correct median position

    operations = 0

    if nums[median_idx] == k:
        return 0

    elif nums[median_idx] < k:
        # Need to increase the median to k
        # All elements from median index onwards that are less than k need to be increased
        for i in range(median_idx, n):
            if nums[i] < k:
                operations += k - nums[i]

    else:
        # nums[median_idx] > k, need to decrease the median to k
        # All elements from median index and before that are greater than k need to be decreased
        for i in range(median_idx + 1):
            if nums[i] > k:
                operations += nums[i] - k

    return operations
