We can treat this as a shortest-path problem between the start, goal, and candies, but we need to maximize candies collected within a move limit.  

Since there are at most 18 candies, we can:  

1. Find all important points: start, goal, candies.  
2. Compute shortest distances between all pairs of important points using BFS.  
3. Use dynamic programming over subsets of candies to find the best route that starts at `S`, ends at `G`, and has total moves ≤ `T`.  

Here’s the implementation:  

```python
from sys import stdin
from collections import deque

def main():
    H, W, T = map(int, stdin.readline().split())
    grid = [stdin.readline().strip() for _ in range(H)]

    # Locate start, goal, and candies
    start = goal = None
    candies = []
    pos_to_id = {}
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    # Assign IDs: 0 = start, then candies, then goal
    points = [start] + candies + [goal]
    n = len(points)
    candy_count = len(candies)

    for idx, pt in enumerate(points):
        pos_to_id[pt] = idx

    # BFS from each important point to compute pairwise distances
    INF = 10 ** 9
    dist_matrix = [[INF] * n for _ in range(n)]

    # Directions
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for idx, (sy, sx) in enumerate(points):
        dq = deque()
        dist = [[-1] * W for _ in range(H)]
        dist[sy][sx] = 0
        dq.append((sy, sx))
        while dq:
            y, x = dq.popleft()
            for dy, dx in dirs:
                ny, nx = y + dy, x + dx
                if 0 <= ny < H and 0 <= nx < W and grid[ny][nx] != '#':
                    if dist[ny][nx] == -1:
                        dist[ny][nx] = dist[y][x] + 1
                        dq.append((ny, nx))
        # Fill dist_matrix[idx][other]
        for j, (ty, tx) in enumerate(points):
            d = dist[ty][tx]
            if d == -1:
                dist_matrix[idx][j] = INF
            else:
                dist_matrix[idx][j] = d

    # If direct start to goal is impossible or too long, check later
    if dist_matrix[0][n - 1] > T:
        # Might still be possible via candies, but if unreachable, print -1
        if dist_matrix[0][n - 1] == INF:
            print(-1)
            return

    # DP[mask][last] = min moves to visit candy set 'mask' ending at 'last'
    # last: 0..candy_count-1 (candy indices), start is separate
    # We'll index candies as 1..candy_count in points list
    # Actually: points[0]=start, points[1..candy_count]=candies, points[candy_count+1]=goal
    # So candy indices in DP: 0..candy_count-1
    # DP size: 2^candy_count * candy_count
    if candy_count == 0:
        # No candies, just check start->goal
        if dist_matrix[0][1] <= T:
            print(0)
        else:
            print(-1)
        return

    DP = [[INF] * candy_count for _ in range(1 << candy_count)]

    # Start from S to each candy
    for i in range(candy_count):
        d = dist_matrix[0][i + 1]  # i+1 because points[0]=start, points[1..]=candies
        if d < INF:
            DP[1 << i][i] = d

    # DP transition
    for mask in range(1 << candy_count):
        for last in range(candy_count):
            if DP[mask][last] >= INF:
                continue
            # Try next candy
            for nxt in range(candy_count):
                if mask >> nxt & 1:
                    continue
                nd = DP[mask][last] + dist_matrix[last + 1][nxt + 1]
                if nd < DP[mask | (1 << nxt)][nxt]:
                    DP[mask | (1 << nxt)][nxt] = nd

    ans = -1
    # Check each subset of candies
    for mask in range(1 << candy_count):
        for last in range(candy_count):
            if DP[mask][last] >= INF:
                continue
            # Go to goal
            total_moves = DP[mask][last] + dist_matrix[last + 1][n - 1]
            if total_moves <= T:
                cnt = bin(mask).count("1")
                ans = max(ans, cnt)

    # Also check direct start->goal without candies
    if dist_matrix[0][n - 1] <= T:
        ans = max(ans, 0)

    print(ans)

if __name__ == "__main__":
    main()
```

