        prereqs[i] = p_list

    # Find all books needed to read book 1
    required = set()
    stack = [1]

    while stack:
        book = stack.pop()
        for pre in prereqs[book]:
            if pre not in required:
                required.add(pre)
                stack.append(pre)

    # Build dependency graph for required books
    graph = defaultdict(list)
    indegree = defaultdict(int)

    for book in required:
        for pre in prereqs[book]:
            if pre in required:
                graph[pre].append(book)
                indegree[book] += 1

    # Add books with no prerequisites
    queue = deque()
    for book in required:
        if indegree[book] == 0:
            queue.append(book)

    # Topological sort
    result = []
    while queue:
        book = queue.popleft()
        result.append(book)
        for next_book in graph[book]:
            indegree[next_book] -= 1
            if indegree[next_book] == 0:
                queue.append(next_book)

