    # Find all beautiful substrings and track the minimum length
    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1

            # If we have exactly k ones, we found a beautiful substring
            if ones_count == k:
                length = j - i + 1
                if length < min_length:
                    min_length = length
                    candidates = [s[i:j+1]]
                elif length == min_length:
                    candidates.append(s[i:j+1])
                break

    # If no beautiful substring found
    if min_length == float('inf'):
        return ""

    # Return lexicographically smallest substring
    return min(candidates)
