    from itertools import permutations

    # Read input
    lines = sys.stdin.read().splitlines()
    if not lines:
        print("No")
        return

    n, h, w = map(int, lines[0].split())
    tiles = []
    for i in range(1, n + 1):
        a, b = map(int, lines[i].split())
        tiles.append((a, b))

    # Total area of the grid
    grid_area = h * w

    # Try all possible subsets of tiles and their permutations
    # Since N <= 7, we can try all 2^N subsets
    from itertools import combinations

    # Check if we can fill the grid using any subset of tiles
    for r in range(1, n + 1):
        for tile_subset in combinations(range(n), r):
            # Get the tiles in this subset, each can be rotated
            subset_tiles = [tiles[i] for i in tile_subset]

            # Calculate total area of selected tiles
            total_area = sum(a * b for a, b in subset_tiles)

            # If area doesn't match, skip
            if total_area != grid_area:
                continue

            # Try to place these tiles on the grid
            # Use backtracking to place rectangles on grid
            def can_fill_grid():
                # Create a h x w grid, 0 means empty, 1 means filled
                grid = [[0 for _ in range(w)] for _ in range(h)]

                # Get all permutations of the subset tiles
                for perm in permutations(subset_tiles):
                    if backtrack(0, grid, perm):
                        return True
                return False

            def backtrack(idx, grid, tile_list):
                if idx == len(tile_list):
                    return True  # All tiles placed successfully

                a, b = tile_list[idx]

                # Try placing tile without rotation (a x b)
                for i in range(h):
                    for j in range(w):
                        if can_place(grid, i, j, a, b):
                            place(grid, i, j, a, b, 1)
                            if backtrack(idx + 1, grid, tile_list):
                                place(grid, i, j, a, b, 0)  # undo
                                return True
                            place(grid, i, j, a, b, 0)  # undo

                # Try placing tile with rotation (b x a) if different
                if a != b:
                    for i in range(h):
                        for j in range(w):
                            if can_place(grid, i, j, b, a):
                                place(grid, i, j, b, a, 1)
                                if backtrack(idx + 1, grid, tile_list):
                                    place(grid, i, j, b, a, 0)  # undo
                                    return True
                                place(grid, i, j, b, a, 0)  # undo

                return False

            def can_place(grid, r, c, height, width):
                if r + height > h or c + width > w:
                    return False
                for i in range(r, r + height):
                    for j in range(c, c + width):
                        if grid[i][j] == 1:
                            return False
                return True

            def place(grid, r, c, height, width, val):
                for i in range(r, r + height):
                    for j in range(c, c + width):
                        grid[i][j] = val

            if can_fill_grid():
