def canTraverseAllPairs(nums):
    if len(nums) == 1:
        return True

    if 1 in nums:
        return False

    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        px, py = find(parent, x), find(parent, y)
        if px == py:
            return
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1

    def get_prime_factors(n):
        factors = set()
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.add(d)
                n //= d
            d += 1
        if n > 1:
            factors.add(n)
        return factors

    # Create union-find structure for indices
    parent = list(range(len(nums)))
    rank = [0] * len(nums)

    # Map each prime factor to the first index that has it
    prime_to_index = {}

    for i, num in enumerate(nums):
        prime_factors = get_prime_factors(num)
        for prime in prime_factors:
            if prime in prime_to_index:
                union(parent, rank, i, prime_to_index[prime])
            else:
                prime_to_index[prime] = i

    # Check if all indices are in the same connected component
    root = find(parent, 0)
    for i in range(1, len(nums)):
        if find(parent, i) != root:
            return False

    return True
