def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute which pairs satisfy the condition
    compatible = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                compatible[i][j] = True

    # dp[mask][last] = number of ways to arrange the elements in mask with last element at index 'last'
    # We'll use memoization with recursion
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(mask, last_idx):
        # Count set bits in mask
        count = bin(mask).count('1')
        if count == n:
            return 1

        result = 0
        for next_idx in range(n):
            # If this element is not used and is compatible with the last element
            if not (mask & (1 << next_idx)) and compatible[last_idx][next_idx]:
                result = (result + dp(mask | (1 << next_idx), next_idx)) % MOD

        return result

    # Try starting with each element
    total = 0
    for i in range(n):
        total = (total + dp(1 << i, i)) % MOD

    return total
